204: export async function startWp01BrowserPool() {
205:   if (pool.sealed || pool.failed || pool.starting || pool.browser || pool.launches !== 0)
206:     throw new Error("WP01 browser startup must run exactly once before every lease")
207:   pool.starting = true
208:   try {
209:     const browser = await startBrowser()
210:     if (!browser.isConnected() || browser.contexts().length !== 0 || pool.lease !== undefined)
211:       throw new Error("WP01 browser startup did not produce a connected, empty pool")
212:     return { launches: pool.launches, pid: pool.pid, connected: browser.isConnected(),
213:       activeLease: pool.lease !== undefined, contexts: browser.contexts().length }
214:   } catch (error) { poison(error); throw error }
215:   finally { pool.starting = false }

247: export async function closeWp01Browser(browser: Browser): Promise<void> {
248:   if (browser !== pool.browser || pool.lease === undefined || pool.releasing || pool.sealed) {
249:     const error = new Error("WP01 browser release does not own an active exclusive lease")
250:     poison(error)
251:     throw error
252:   }
253:   pool.releasing = true
254:   const failures: unknown[] = []
255:   const contexts = browser.contexts()
256:   try {
257:     try {
258:       const outcomes = await bounded(Promise.allSettled(contexts.flatMap((context) => context.pages().map((page) => page.close({ runBeforeUnload: false })))), "close lease pages", 5_000)
259:       for (const outcome of outcomes) if (outcome.status === "rejected") failures.push(outcome.reason)
260:     } catch (error) { failures.push(error) }
261:     try {
262:       const outcomes = await bounded(Promise.allSettled(contexts.map((context) => context.close())), "close lease contexts", 5_000)
263:       for (const outcome of outcomes) if (outcome.status === "rejected") failures.push(outcome.reason)
264:     } catch (error) { failures.push(error) }
265:     if (!browser.isConnected()) failures.push(new Error("WP01 browser disconnected during lease release"))
266:     if (browser.contexts().length !== 0) failures.push(new Error("WP01 browser contexts remain after lease release"))
267:     if (failures.length) throw new AggregateError(failures, "WP01 browser lease cleanup failed")
268:     pool.releases++
269:     console.info("WP01 browser lease released", { pid: pool.pid, lease: pool.lease, releases: pool.releases, contexts: 0 })
270:     pool.lease = undefined
271:   } catch (error) { poison(error); throw error }
272:   finally { pool.releasing = false }

